import sys
from collections import Counter

def top_k_best(nums, k):
    cnt = Counter(nums)
    bucket = [[] for _ in range(len(nums) + 1)]
    for v, c in cnt.items():
        bucket[c].append(v)
    res = []
    for c in range(len(nums), 0, -1):
        for v in sorted(bucket[c]):
            res.append(v)
            if len(res) == k:
                return res
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    k = int(data[1 + n])
    print(' '.join(map(str, top_k_best(nums, k))))
